insert into abonos(cliente_id,tipo,plan,estado,notas) select c.id,v.t,v.p,'Activo','Migrado de la planilla de operaciones (servicio mensual vigente según facturación sep/oct-2026)' from (values ('Apromax','Redes','SMALL'),('Apromax','Ads',''),('Barbalé','Redes','MEDIUM'),('Calasanz','Redes','MEDIUM'),('Calasanz','Ads',''),('Chango','Redes','LARGE'),('El Cultu','Redes','PREMIUM'),('Facultad de Lenguas','Redes','PACK RRSS'),('Lomo Loco','Redes','LARGE'),('Lomo Loco','Ads',''),('Lucrecia Lascano','Redes','MEDIUM'),('P4 Desarrollistas','Redes','SMALL+ADS'),('Pasta Fusión','Redes','SMALL'),('Pasta Fusión','Ads',''),('Punto Íntimo','Redes','LARGE'),('Rhyza','Redes','MEDIUM'),('XIPA','Redes','SMALL')) v(c,t,p) join clientes c on c.nombre=v.c;
insert into abono_responsables select a.id,(select id from personas where alias='Fer') from abonos a join clientes c on c.id=a.cliente_id where c.nombre='Apromax' and a.tipo='Ads';
